pub struct DefaultValueBuilder<'a: 'b, 'b> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b> DefaultValueBuilder<'a, 'b> {
  #[inline]
  pub fn add_field(&mut self, field: flatbuffers::WIPOffset<&'b  str>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(DefaultValue::VT_FIELD, field);
  }
  #[inline]
  pub fn add_value_type(&mut self, value_type: Value) {
    self.fbb_.push_slot::<Value>(DefaultValue::VT_VALUE_TYPE, value_type, Value::NONE);
  }
  #[inline]
  pub fn add_value(&mut self, value: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(DefaultValue::VT_VALUE, value);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>) -> DefaultValueBuilder<'a, 'b> {
    let start = _fbb.start_table();
    DefaultValueBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<DefaultValue<'a>> {
    let o = self.fbb_.end_table(self.start_);
    self.fbb_.required(o, DefaultValue::VT_FIELD,"field");
    self.fbb_.required(o, DefaultValue::VT_VALUE,"value");
    flatbuffers::WIPOffset::new(o.value())
  }
}

