pub enum IngestionOffset {}
#[derive(Copy, Clone, PartialEq)]

pub struct Ingestion<'a> {
  pub _tab: flatbuffers::Table<'a>,
}

impl<'a> flatbuffers::Follow<'a> for Ingestion<'a> {
  type Inner = Ingestion<'a>;
  #[inline]
  unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
    Self { _tab: flatbuffers::Table::new(buf, loc) }
  }
}

impl<'a> Ingestion<'a> {
  pub const VT_TARGET: flatbuffers::VOffsetT = 4;
  pub const VT_LOG: flatbuffers::VOffsetT = 6;
  pub const VT_TRANSFORM_TYPE: flatbuffers::VOffsetT = 8;
  pub const VT_TRANSFORM: flatbuffers::VOffsetT = 10;
  pub const VT_DEFAULTS: flatbuffers::VOffsetT = 12;

  #[inline]
  pub unsafe fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
    Ingestion { _tab: table }
  }
  #[allow(unused_mut)]
  pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr>(
    _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr>,
    args: &'args IngestionArgs<'args>
  ) -> flatbuffers::WIPOffset<Ingestion<'bldr>> {
    let mut builder = IngestionBuilder::new(_fbb);
    if let Some(x) = args.defaults { builder.add_defaults(x); }
    if let Some(x) = args.transform { builder.add_transform(x); }
    if let Some(x) = args.log { builder.add_log(x); }
    if let Some(x) = args.target { builder.add_target(x); }
    builder.add_transform_type(args.transform_type);
    builder.finish()
  }


  /// The target into which we ingest the data. This may be a stream or
  /// even another Ingestion object.
  #[inline]
  pub fn target(&self) -> ObjectId<'a> {
    // Safety:
    // Created from valid Table for this object
    // which contains a valid value in this slot
    unsafe { self._tab.get::<flatbuffers::ForwardsUOffset<ObjectId>>(Ingestion::VT_TARGET, None).unwrap()}
  }
  /// Drive directory into which we store the ingestion log
  #[inline]
  pub fn log(&self) -> Option<ObjectId<'a>> {
    // Safety:
    // Created from valid Table for this object
    // which contains a valid value in this slot
    unsafe { self._tab.get::<flatbuffers::ForwardsUOffset<ObjectId>>(Ingestion::VT_LOG, None)}
  }
  #[inline]
  pub fn transform_type(&self) -> Transform {
    // Safety:
    // Created from valid Table for this object
    // which contains a valid value in this slot
    unsafe { self._tab.get::<Transform>(Ingestion::VT_TRANSFORM_TYPE, Some(Transform::NONE)).unwrap()}
  }
  /// The data transformation to apply to the inbound data.
  #[inline]
  pub fn transform(&self) -> flatbuffers::Table<'a> {
    // Safety:
    // Created from valid Table for this object
    // which contains a valid value in this slot
    unsafe { self._tab.get::<flatbuffers::ForwardsUOffset<flatbuffers::Table<'a>>>(Ingestion::VT_TRANSFORM, None).unwrap()}
  }
  /// If the incoming data may be missing, we can specify the default
  /// value here so that the transform can succeed.
  #[inline]
  pub fn defaults(&self) -> Option<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<DefaultValue<'a>>>> {
    // Safety:
    // Created from valid Table for this object
    // which contains a valid value in this slot
    unsafe { self._tab.get::<flatbuffers::ForwardsUOffset<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<DefaultValue>>>>(Ingestion::VT_DEFAULTS, None)}
  }
  #[inline]
  #[allow(non_snake_case)]
  pub fn transform_as_query(&self) -> Option<Query<'a>> {
    if self.transform_type() == Transform::Query {
      let u = self.transform();
      // Safety:
      // Created from a valid Table for this object
      // Which contains a valid union in this slot
      Some(unsafe { Query::init_from_table(u) })
    } else {
      None
    }
  }

}

impl flatbuffers::Verifiable for Ingestion<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<flatbuffers::ForwardsUOffset<ObjectId>>("target", Self::VT_TARGET, true)?
     .visit_field::<flatbuffers::ForwardsUOffset<ObjectId>>("log", Self::VT_LOG, false)?
     .visit_union::<Transform, _>("transform_type", Self::VT_TRANSFORM_TYPE, "transform", Self::VT_TRANSFORM, true, |key, v, pos| {
        match key {
          Transform::Query => v.verify_union_variant::<flatbuffers::ForwardsUOffset<Query>>("Transform::Query", pos),
          _ => Ok(()),
        }
     })?
     .visit_field::<flatbuffers::ForwardsUOffset<flatbuffers::Vector<'_, flatbuffers::ForwardsUOffset<DefaultValue>>>>("defaults", Self::VT_DEFAULTS, false)?
     .finish();
    Ok(())
  }
}
pub struct IngestionArgs<'a> {
    pub target: Option<flatbuffers::WIPOffset<ObjectId<'a>>>,
    pub log: Option<flatbuffers::WIPOffset<ObjectId<'a>>>,
    pub transform_type: Transform,
    pub transform: Option<flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>>,
    pub defaults: Option<flatbuffers::WIPOffset<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<DefaultValue<'a>>>>>,
}
impl<'a> Default for IngestionArgs<'a> {
  #[inline]
  fn default() -> Self {
    IngestionArgs {
      target: None, // required field
      log: None,
      transform_type: Transform::NONE,
      transform: None, // required field
      defaults: None,
    }
  }
}

impl Serialize for Ingestion<'_> {
  fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
  where
    S: Serializer,
  {
    let mut s = serializer.serialize_struct("Ingestion", 5)?;
      s.serialize_field("target", &self.target())?;
      if let Some(f) = self.log() {
        s.serialize_field("log", &f)?;
      } else {
        s.skip_field("log")?;
      }
      s.serialize_field("transform_type", &self.transform_type())?;
      match self.transform_type() {
        Transform::NONE => (),
          Transform::Query => {
            let f = self.transform_as_query()
              .expect("Invalid union table, expected `Transform::Query`.");
            s.serialize_field("transform", &f)?;
          }
        _ => unimplemented!(),
      }
      if let Some(f) = self.defaults() {
        s.serialize_field("defaults", &f)?;
      } else {
        s.skip_field("defaults")?;
      }
    s.end()
  }
}

pub struct IngestionBuilder<'a: 'b, 'b> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b> IngestionBuilder<'a, 'b> {
  #[inline]
  pub fn add_target(&mut self, target: flatbuffers::WIPOffset<ObjectId<'b >>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<ObjectId>>(Ingestion::VT_TARGET, target);
  }
  #[inline]
  pub fn add_log(&mut self, log: flatbuffers::WIPOffset<ObjectId<'b >>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<ObjectId>>(Ingestion::VT_LOG, log);
  }
  #[inline]
  pub fn add_transform_type(&mut self, transform_type: Transform) {
    self.fbb_.push_slot::<Transform>(Ingestion::VT_TRANSFORM_TYPE, transform_type, Transform::NONE);
  }
  #[inline]
  pub fn add_transform(&mut self, transform: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Ingestion::VT_TRANSFORM, transform);
  }
  #[inline]
  pub fn add_defaults(&mut self, defaults: flatbuffers::WIPOffset<flatbuffers::Vector<'b , flatbuffers::ForwardsUOffset<DefaultValue<'b >>>>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Ingestion::VT_DEFAULTS, defaults);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>) -> IngestionBuilder<'a, 'b> {
    let start = _fbb.start_table();
    IngestionBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<Ingestion<'a>> {
    let o = self.fbb_.end_table(self.start_);
    self.fbb_.required(o, Ingestion::VT_TARGET,"target");
    self.fbb_.required(o, Ingestion::VT_TRANSFORM,"transform");
    flatbuffers::WIPOffset::new(o.value())
  }
}

